RequestErrorModel: type[BaseModel] = create_model("Request")


def _normalize_errors(errors: Sequence[Any]) -> list[dict[str, Any]]:
    use_errors: list[Any] = []
    for error in errors:
        if isinstance(error, ErrorWrapper):
            new_errors = ValidationError(
